using System;
using System.Buffers;
using System.Collections.Generic;
using System.IO;
using System.Text.Json;

public class LedgerSnapshotPipeline
{
    public IEnumerable<string> EnumerateIds(Stream stream)
    {
        var buffer = ArrayPool<byte>.Shared.Rent(4096);
        try
        {
            var state = new JsonReaderState();
            var ids = new List<string>();
            int read;
            while ((read = stream.Read(buffer, 0, buffer.Length)) > 0)
            {
                var reader = new Utf8JsonReader(new ReadOnlySpan<byte>(buffer, 0, read), false, state);
                while (reader.Read())
                {
                    if (reader.TokenType == JsonTokenType.PropertyName && reader.ValueTextEquals("id"))
                    {
                        reader.Read();
                        ids.Add(reader.GetString());
                    }
                }
                state = reader.CurrentState;
            }
            return ids;
        }
        finally
        {
            ArrayPool<byte>.Shared.Return(buffer, clearArray: true);
        }
    }
}

