using System;
using System.IO;

public class LargeBufferBuilder
{
    public byte[] Capture(Stream stream)
    {
        using var ms = new MemoryStream();
        stream.CopyTo(ms);
        var data = ms.ToArray();
        var copy = new byte[data.Length + 1024 * 1024];
        Buffer.BlockCopy(data, 0, copy, 0, data.Length);
        return copy;
    }
}

using System;
using System.Buffers;
using System.IO;

public class ReusedBufferBuilder
{
    public byte[] Capture(Stream stream)
    {
        var pool = ArrayPool<byte>.Shared;
        var buffer = pool.Rent(65536);
        try
        {
            using var ms = new MemoryStream();
            int read;
            while ((read = stream.Read(buffer, 0, buffer.Length)) > 0)
            {
                ms.Write(buffer, 0, read);
            }
            return ms.ToArray();
        }
        finally
        {
            pool.Return(buffer, clearArray: true);
        }
    }
}

