public class BatchShipmentStreamer
{
    public IEnumerable<ShipmentRecord> Parse(Stream stream)
    {
        var buffer = ArrayPool<byte>.Shared.Rent(4096);
        try
        {
            var state = new JsonReaderState();
            while (true)
            {
                var read = stream.Read(buffer, 0, buffer.Length);
                if (read == 0)
                {
                    yield break;
                }
                var reader = new Utf8JsonReader(new ReadOnlySpan<byte>(buffer, 0, read), false, state);
                while (reader.Read())
                {
                    if (reader.TokenType == JsonTokenType.StartObject)
                    {
                        yield return JsonSerializer.Deserialize<ShipmentRecord>(ref reader);
                    }
                }
                state = reader.CurrentState;
            }
        }
        finally
        {
            ArrayPool<byte>.Shared.Return(buffer, clearArray: true);
        }
    }
}

