public class LargeBufferDuplicator
{
    public byte[] Duplicate(Stream source)
    {
        using var ms = new MemoryStream();
        source.CopyTo(ms);
        var data = ms.ToArray();
        var growth = new byte[data.Length + 524288];
        Buffer.BlockCopy(data, 0, growth, 0, data.Length);
        return growth;
    }
}

using System;
using System.Buffers;
using System.IO;

public class LargeBufferDuplicatorPooled
{
    public byte[] Duplicate(Stream source)
    {
        var pool = ArrayPool<byte>.Shared;
        var buffer = pool.Rent(65536);
        try
        {
            using var ms = new MemoryStream();
            int read;
            while ((read = source.Read(buffer, 0, buffer.Length)) > 0)
            {
                ms.Write(buffer, 0, read);
            }
            return ms.ToArray();
        }
        finally
        {
            pool.Return(buffer, clearArray: true);
        }
    }
}

