using System;
using System.Buffers;
using System.Collections.Generic;
using System.IO;
using System.Text.Json;

public class StatusLoaderStreaming
{
    public IEnumerable<StatusRecord> Load(Stream stream)
    {
        var rent = ArrayPool<byte>.Shared.Rent(4096);
        try
        {
            var state = new JsonReaderState();
            while (true)
            {
                var read = stream.Read(rent, 0, rent.Length);
                if (read == 0)
                {
                    yield break;
                }
                var reader = new Utf8JsonReader(new ReadOnlySpan<byte>(rent, 0, read), false, state);
                while (reader.Read())
                {
                    if (reader.TokenType == JsonTokenType.StartObject)
                    {
                        yield return JsonSerializer.Deserialize<StatusRecord>(ref reader);
                    }
                }
                state = reader.CurrentState;
            }
        }
        finally
        {
            ArrayPool<byte>.Shared.Return(rent, clearArray: true);
        }
    }
}

