public class LegacyBufferFactory
{
    public byte[] Create(Stream stream)
    {
        using var ms = new MemoryStream();
        stream.CopyTo(ms);
        var data = ms.ToArray();
        var expanded = new byte[data.Length + 262144];
        Buffer.BlockCopy(data, 0, expanded, 0, data.Length);
        return expanded;
    }
}

using System;
using System.Buffers;
using System.IO;

public class BufferFactoryPooled
{
    public byte[] Create(Stream stream)
    {
        var pool = ArrayPool<byte>.Shared;
        var buffer = pool.Rent(32768);
        try
        {
            using var ms = new MemoryStream();
            int read;
            while ((read = stream.Read(buffer, 0, buffer.Length)) > 0)
            {
                ms.Write(buffer, 0, read);
            }
            return ms.ToArray();
        }
        finally
        {
            pool.Return(buffer, clearArray: true);
        }
    }
}

