        {
            var state = new JsonReaderState();
            while (true)
            {
                var read = stream.Read(buffer, 0, buffer.Length);
                if (read == 0)
                {
                    yield break;
                }
                var reader = new Utf8JsonReader(new ReadOnlySpan<byte>(buffer, 0, read), false, state);
