using Tizen.TV;

public class InvoiceAggregatorMap
{
    public decimal Sum(JsonMap map)
    {
        JsonMapNode invoices = map.GetNode("invoices");
        if (!map.CheckValueInt(invoices, out var count))
        {
            return 0m;
        }
        decimal total = 0;
        for (int i = 0; i < count; i++)
        {
            JsonMapNode node = map.GetNode($"invoices[{i}].amount");
            if (map.CheckValueDbl(node, out var amount))
            {
                total += (decimal)amount;
            }
        }
        return total;
    }
}

